import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { content, send } from '../runtime/helpers.mjs';
import { decodeSave, encodeSave } from '../../dist/packages/runtime-service/save.js';

test('pre-migration save restores unchanged legacy state and continues without journey fields', async () => {
  const snapshot = await content();
  // Captured before the native/free-screen migration; never regenerated by this test.
  const text = await readFile(new URL('./fixtures/pre-migration-save.json', import.meta.url), 'utf8');
  const expected = JSON.parse(text);
  const restored = await decodeSave(snapshot, text);
  assert.equal(restored.ok, true, JSON.stringify(restored));
  assert.deepEqual(restored.session.state, expected.state);
  assert.equal('journey' in restored.session.state, false);
  assert.equal('inventory' in restored.session.state, false);
  const advanced = send(snapshot, restored.session, { type: 'acknowledgeResult' });
  assert.equal(advanced.state.phase, 'period-end');
  assert.equal(advanced.state.stateRevision, expected.state.stateRevision + 1);
  const encoded = await encodeSave(snapshot, advanced);
  assert.equal(encoded.ok, true, JSON.stringify(encoded));
  const second = await decodeSave(snapshot, encoded.text);
  assert.equal(second.ok, true, JSON.stringify(second));
  assert.deepEqual(second.session, advanced);
});
